"""README results table and Phase 5 results bullets, generated from the warehouse so the numbers cannot go stale.

The wording lives in the two templates below; only the numbers come from the marts. README.md carries two marked regions:

    <!-- results-table: generated by scripts/build_readme_results.py (make docs); edit the script, not this block -->
    <!-- p5-results: generated by scripts/build_readme_results.py (make docs); edit the script, not this block -->

  uv run python -m scripts.build_readme_results           rewrites both regions in README.md
  uv run python -m scripts.build_readme_results --check   exits 1 if README.md differs from what the warehouse says
  uv run python -m scripts.build_readme_results --diff    prints the numbers that differ (what the README says -> what the warehouse says)

Every number is read from the same marts as the matching `make` printout (named in each row). A few are derived on purpose and the
derivation is stated next to the query. Nothing here is computed in the README text itself.
"""
from __future__ import annotations

import difflib
import re
import sys

import duckdb
from scripts.common import DB, ROOT

README = ROOT / "README.md"
TABLE_TAG = "results-table"
P5_TAG = "p5-results"


def marker(tag: str, end: bool = False) -> str:
    return f"<!-- /{tag} -->" if end else f"<!-- {tag}: generated by scripts/build_readme_results.py (make docs); edit the script, not this block -->"


TABLE = """| What | Result |
|---|---|
| **Fan accounts the programme added** (incremental, stacked market-launch comparison) | **{acq_est}** (95% interval {acq_lo} to {acq_hi}); truth {acq_truth}. The naive count of net-new households is {naive_obs} linked ({naive_obs_x}x the truth) and {naive_sc} scaled by the link rate (**{naive_sc_x}x**) (`make acquisition`) |
| **Addressable audience** (guardian opted in on at least one channel, December {aud_year}) | **{aud_contactable} of {aud_registered}** registered households (email {aud_email}, SMS {aud_sms}, push {aud_push}; channels overlap) (`make audience`) |
| **Consent gap** (active households with no opt-in at all) | **{gap_hh} households, about {gap_pct}% of the active**, worth about {gap_value} in synthetic currency at the median monetized household's spend (an opportunity size, not revenue) |
| Fan lifetime value (36-month horizon, synthetic currency) | existing fans {ltv_ex} ({ltv_ex_lo} to {ltv_ex_hi}), net-new {ltv_nn_lo_pt} to {ltv_nn_hi_pt} ({ltv_nn_lo} to {ltv_nn_hi}); 12-month survival {surv_ex}% for existing fans, {surv_nn}% for net-new (`make fan-value`) |
| Value uplift after registering a child (existing fans) | +{val_events} events per household-month (truth +{val_events_truth}); net spend up about {val_spend} per household-month (synthetic currency; truth {val_spend_truth}, {val_spend_inside} the interval) |
| Fan engagement uplift after first registration (linked households) | naive +{fan_naive}% (truth +{fan_naive_truth}%), matched difference-in-differences +{fan_did}% (truth +{fan_did_truth}%) (`make fan`) |
| Markets ({q_total} synthetic) | {q_retention} retention-and-engagement, {q_growth} program-growth, {q_white} acquisition white space, {q_build} long-term build |
| Unique registered participants | {id_point} in {id_year} (identity range {id_lo} to {id_hi}, a {id_band}% band) |
| Identity resolution, final matcher (`fs`, automatic merges) | precision {fs_prec}%, recall {fs_rec}%; **{fs_sib} sibling/twin false merges (a finding, not yet fixed: ADR-008)**; {fs_pred} predicted vs {fs_true} true people (`make eval`) |
| Rules baseline vs probabilistic | rules recall {rules_rec}% ({rules_pred} predicted people, {rules_sib_text}); literal Fellegi-Sunter `fs_naive` makes {naive_sib} sibling merges; the corrected `fs` makes {fs_sib} |
| One-year retention of entrants (Kaplan-Meier, censored) | {ret_km}% (truth {ret_truth}%); counting age-outs as churn would report {ret_naive}% for entrants aged 14 to 17 (truth {ret_naive_truth}%) (`make retention`) |
| Household link rate (registration to fan account) | {link_rate}% overall; email links {link_email}% precise, phone links {link_phone}% (UNLINKED means unknown: about {link_unlinked_have}% of unlinked households do have an account) (`make linkage`) |"""

P5 = """- **The scorecard separates the worst profile from the rest, but barely the middle.** MANUAL organizations score {sc_manual_act} for activation against {sc_other_act} for the others, and {sc_manual_ret} for retention against {sc_other_ret}; STRUGGLING is hard to tell from TYPICAL without labels (`eval_scorecard_vs_profile`). Every organization-based source caps near {sc_cap} under the minimum rule because organizations that sent late or no files pull timeliness down.
- **Identity bounds held; the coverage estimate only partly.** In {id_words} years the identity interval contains the true number of people in the data. The coverage interval (the estimate for organizations that sent no file) contains the truth in {cov_ok} of {cov_n} years, with point errors from {cov_err_lo}% to {cov_err_hi}%. It was not tuned after seeing this.
- **Missing gender is biased, not just sparse.** Blank genders concentrate in the youngest divisions and in spreadsheet files; the girls' share bounds are narrow at participant level ({girls_unknown}% unknown) and the verdict is "{girls_verdict}".
- **Consent: most recorded opt-ins are not evidence of the purpose.** {optin_unnamed}% of recorded marketing opt-ins are on a form whose wording never names club marketing. In {fun_year}, of {fun_hh} households {fun_consenting} are consenting with full provenance; the loss to consent is {fun_privacy} PRIVACY (declined or revoked) and {fun_dq} data quality. Of the {contacts} contacts on the Phase 3 marketing list, {contacts_full} match a fully evidenced consent (reported, not changed; question 14).
- **Minimization: dropping the day of birth and ZIP5 costs the matcher almost nothing here.** Uniqueness falls from {min_unique_v0}% to {min_unique_v2}% of participant-years and sibling/twin merges from {min_sib_v0} to {min_sib_v2} (one synthetic dataset). Dropping the phone costs accuracy; hashing the email costs the whole activation purpose. No variant reaches `k_min`. The data standard cites **V2** (birth year, ZIP3; chosen by Anna) ([ADR-018](docs/decisions/ADR-018-minimization-and-data-standard.md)).
- **Deletion: the retention marts survive if the pseudonymous key is kept.** Rebuilt from anonymized facts they are unchanged; if identity resolution is re-run on the anonymized inputs, participants inflate {del_inflate}% and retention falls about {del_retention}% ([ADR-017](docs/decisions/ADR-017-retention-vs-deletion.md)).
- **Fixing upstream helps the organization, not the coverage gap** (simulated, [`docs/reports/fix_list_demo.md`](docs/reports/fix_list_demo.md)).
- **A defect found on the way.** Stale API pages from an earlier generator run were being loaded with the current ones; the generator now clears each source folder first, and the evaluation notes were refreshed."""


def n0(x) -> str:
    return f"{x:,.0f}"


def numbers(con: duckdb.DuckDBPyConnection) -> dict[str, str]:
    q = lambda sql: con.execute(sql).fetchall()  # noqa: E731
    one = lambda sql: q(sql)[0]  # noqa: E731
    v: dict[str, str] = {}

    # `make acquisition`: evaluation.eval_acquisition (the model, its range, the generator's truth, and the two naive counts)
    acq = {r[0]: r for r in q("select measure, estimate, ci_low, ci_high, truth, estimate_over_truth from evaluation.eval_acquisition "
                              "where measure in ('incremental_accounts', 'naive_net_new_observed', 'naive_net_new_scaled_by_link_rate')")}
    m = acq["incremental_accounts"]
    v.update(acq_est=n0(m[1]), acq_lo=n0(m[2]), acq_hi=n0(m[3]), acq_truth=n0(m[4]))
    v.update(naive_obs=n0(acq["naive_net_new_observed"][1]), naive_obs_x=f"{acq['naive_net_new_observed'][5]:.2f}",
             naive_sc=n0(acq["naive_net_new_scaled_by_link_rate"][1]), naive_sc_x=f"{acq['naive_net_new_scaled_by_link_rate'][5]:.1f}")

    # `make audience`: linkage.mart_addressable_audience, household group ALL, December of the last year
    y, reg, contact, em, sms, push, active, gap_hh, gap_val = one(
        "select year(month), households_registered, contactable_households, contactable_email, contactable_sms, contactable_push, active_households, "
        "consent_gap_households, consent_gap_value from linkage.mart_addressable_audience where household_group = 'ALL' and month(month) = 12 order by 1 desc limit 1")
    v.update(aud_year=str(y), aud_contactable=n0(contact), aud_registered=n0(reg), aud_email=n0(em), aud_sms=n0(sms), aud_push=n0(push),
             gap_hh=n0(gap_hh), gap_pct=f"{100 * gap_hh / active:.0f}", gap_value=n0(round(gap_val, -3)))   # the value is an opportunity size: rounded to thousands

    # `make fan-value`: linkage.mart_fan_ltv and mart_fan_survival (all market types); net-new = the two net-new groups
    ltv = {r[0]: r for r in q("select s.fan_group, max(s.survival) filter (where months_since_origin = 12), any_value(l.ltv), any_value(l.ltv_low), any_value(l.ltv_high) "
                              "from linkage.mart_fan_survival s join linkage.mart_fan_ltv l on l.fan_group = s.fan_group and l.market_type = s.market_type "
                              "where s.market_type = 'ALL' group by 1")}
    ex, nn = ltv["EXISTING_FAN"], [ltv["NET_NEW_FLAG_PROMPT"], ltv["NET_NEW_OTHER"]]
    v.update(ltv_ex=n0(ex[2]), ltv_ex_lo=n0(ex[3]), ltv_ex_hi=n0(ex[4]),
             ltv_nn_lo_pt=n0(min(r[2] for r in nn)), ltv_nn_hi_pt=n0(max(r[2] for r in nn)), ltv_nn_lo=n0(min(r[3] for r in nn)), ltv_nn_hi=n0(max(r[4] for r in nn)),
             surv_ex=f"{100 * ex[1]:.0f}", surv_nn=f"{100 * ltv['NET_NEW_FLAG_PROMPT'][1]:.0f}")      # net-new survival: the flag-prompt group (the other is within a point)

    # `make fan-value`: evaluation.eval_fan_value_uplift, fans who already had an account
    up = {r[0]: r for r in q("select outcome, did_per_month, did_ci_low_per_month, did_ci_high_per_month, truth_per_month, truth_in_ci_per_month "
                             "from evaluation.eval_fan_value_uplift where status_group = 'EXISTING' and outcome in ('events', 'net_spend_total')")}
    v.update(val_events=f"{up['events'][1]:.2f}", val_events_truth=f"{up['events'][4]:.3f}", val_spend=f"{up['net_spend_total'][1]:.1f}",
             val_spend_truth=f"{up['net_spend_total'][4]:.1f}", val_spend_inside="inside" if up["net_spend_total"][5] else "outside")

    # `make fan`: evaluation.eval_fan_effect
    fe = {r[0]: r for r in q("select estimator, estimate_pct, true_effect_pct from evaluation.eval_fan_effect")}
    v.update(fan_naive=f"{100 * fe['NAIVE'][1]:.1f}", fan_naive_truth=f"{100 * fe['NAIVE'][2]:.1f}",
             fan_did=f"{100 * fe['DID_ADDITIVE'][1]:.1f}", fan_did_truth=f"{100 * fe['DID_ADDITIVE'][2]:.1f}")     # stored as fractions

    # the market quadrants on the site: share_exec.share_exec__market_quadrants
    qd = dict(q("select quadrant, count(*) from share_exec.share_exec__market_quadrants group by 1"))
    v.update(q_total=str(sum(qd.values())), q_retention=str(qd.get("Retention and engagement play", 0)), q_growth=str(qd.get("Program growth opportunity", 0)),
             q_white=str(qd.get("Acquisition white space", 0)), q_build=str(qd.get("Long-term build", 0)))

    # unique participants and the identity range: measurement.mart_identity_uncertainty, global grain, last year
    yr, lo, pt, hi, rng = one("select participation_year, participants_low, participants_point, participants_high, range_pct from measurement.mart_identity_uncertainty "
                              "where grain = 'GLOBAL' order by 1 desc limit 1")
    v.update(id_year=str(yr), id_lo=n0(lo), id_point=n0(pt), id_hi=n0(hi), id_band=f"{100 * rng:.1f}")

    # `make eval`: evaluation.eval_pairwise and eval_clusters, final stage, automatic merges only (the same join as print_headline)
    hl = {(r[0], r[1]): r for r in q("select p.matcher, p.stage, p.precision, p.recall, c.sibling_or_twin_false_merges, c.predicted_participants, c.true_participants "
                                     "from evaluation.eval_pairwise p join evaluation.eval_clusters c using (matcher, stage, scope) where p.scope = 'AUTO'")}
    fs, rules, naive = hl[("fs", "POST_REVIEW")], hl[("rules", "POST_REVIEW")], hl[("fs_naive", "POST_REVIEW")]
    v.update(fs_prec=f"{100 * fs[2]:.2f}", fs_rec=f"{100 * fs[3]:.2f}", fs_sib=str(fs[4]), fs_pred=n0(fs[5]), fs_true=n0(fs[6]),
             rules_rec=f"{100 * rules[3]:.1f}", rules_pred=n0(rules[5]), rules_sib_text="no sibling merges" if rules[4] == 0 else f"{rules[4]} sibling merges", naive_sib=str(naive[4]))

    # `make retention`: evaluation.eval_retention
    r1 = one("select km_survival, true_survival from evaluation.eval_retention where segment_type = 'ALL' and years_since_entry = 1")
    r2 = one("select naive_survival, true_survival from evaluation.eval_retention where segment_type = 'entry_age_band' and segment_value = '14-17' and years_since_entry = 1")
    v.update(ret_km=f"{100 * r1[0]:.1f}", ret_truth=f"{100 * r1[1]:.1f}", ret_naive=f"{100 * r2[0]:.1f}", ret_naive_truth=f"{100 * r2[1]:.1f}")

    # `make linkage`: linkage.linkage_summary and evaluation.eval_household_linkage
    ls = {(r[0], r[1]): r for r in q("select measure, detail, n, share from linkage.linkage_summary")}
    hh = {r[0]: r for r in q("select measure, n, value from evaluation.eval_household_linkage")}
    households, linked = ls[("households", "ALL")][2], ls[("linked_households", "ALL")]
    have_account, correct = hh["participant_households_with_an_account"][1], hh["links_correct"][1]
    v.update(link_rate=f"{100 * linked[3]:.0f}", link_email=f"{100 * hh['precision_EMAIL'][2]:.0f}", link_phone=f"{100 * hh['precision_PHONE'][2]:.1f}",
             link_unlinked_have=f"{100 * (have_account - correct) / (households - linked[2]):.0f}")    # accounts the matcher could not link, over the households left unlinked

    # Phase 5: the scorecard against the generator's latent profile (evaluation.eval_scorecard_vs_profile)
    sp = {(r[0], r[1]): r[2] for r in q("select profile, purpose, mean_purpose_score from evaluation.eval_scorecard_vs_profile")}
    span = lambda vals: f"{round(min(vals))}" if round(min(vals)) == round(max(vals)) else f"{round(min(vals))} to {round(max(vals))}"  # noqa: E731
    others = [p for p in {k[0] for k in sp} if p != "MANUAL"]
    v.update(sc_manual_act=f"{sp[('MANUAL', 'ACTIVATE')]:.0f}", sc_other_act=span([sp[(p, "ACTIVATE")] for p in others]),
             sc_manual_ret=f"{sp[('MANUAL', 'RETAIN')]:.0f}", sc_other_ret=span([sp[(p, "RETAIN")] for p in others]))
    # "caps near": the lowest, over organization-based sources, of the best non-ACTIVATE purpose score in the last season
    cap = one("select min(best) from (select source_system, max(score) as best from quality.dq_scorecard_source where dimension = 'PURPOSE_SCORE' and purpose <> 'ACTIVATE' "
              "and known_orgs is not null and season_year = (select max(season_year) from quality.dq_scorecard_source) group by 1)")[0]
    v["sc_cap"] = f"{cap:.0f}"

    # Phase 5: identity and coverage bounds against the answer key (evaluation.eval_uncertainty_decomposition, printed by `make nuance`)
    ev = q("select identity_interval_contains_truth, coverage_interval_contains_truth, coverage_point_error from evaluation.eval_uncertainty_decomposition")
    n_years = len(ev)
    all_id = all(r[0] for r in ev)
    v.update(id_words=("all " + {5: "five", 4: "four", 3: "three"}.get(n_years, str(n_years))) if all_id else f"{sum(bool(r[0]) for r in ev)} of {n_years}",
             cov_ok=str(sum(bool(r[1]) for r in ev)), cov_n=str(n_years),
             cov_err_lo=f"{100 * min(r[2] for r in ev):.0f}", cov_err_hi=f"+{100 * max(r[2] for r in ev):.0f}")

    # missing gender: quality.mart_missingness_bias, all markets, youth girls' share, last year
    g = one("select unknown, total, missingness_verdict from quality.mart_missingness_bias where kpi = 'girls_share_of_youth' and segment_value = 'ALL' and club_market_id = 'ALL' "
            "order by participation_year desc limit 1")
    v.update(girls_unknown=f"{100 * g[0] / g[1]:.1f}", girls_verdict=g[2].lower().replace("_", " "))

    # consent (`make consent`): linkage.int_consent_event, the activation funnel, and the Phase 3 contact list against the consent chain
    gr = dict(((r[0], r[1]), r[2]) for r in q("select status, has_purpose_coverage, count(*) from linkage.int_consent_event where event_kind = 'MARKETING_OPT_IN' group by all"))
    granted_unnamed = sum(n for (s, cov), n in gr.items() if s == "GRANTED" and not cov)
    granted = sum(n for (s, cov), n in gr.items() if s == "GRANTED")
    v["optin_unnamed"] = f"{100 * granted_unnamed / granted:.0f}"
    fy = one("select max(participation_year) from quality.mart_activation_funnel")[0]
    fun = {r[0]: r for r in q(f"select step_no, n, lost_dq, lost_privacy from quality.mart_activation_funnel where participation_year = {fy} and market_id = 'ALL' order by 1")}
    last = max(fun)
    v.update(fun_year=str(fy), fun_hh=n0(fun[3][1]), fun_consenting=n0(fun[last][1]), fun_privacy=n0(fun[last][3]), fun_dq=n0(fun[last][2]))
    # the Phase 3 marketing contact list against the household consent chain (same query as `make consent`)
    cts = con.execute("""
        with c as (select contact_email from share_marketing.share_marketing__contact_list),
        hh as (select distinct c.contact_email, s.marketing_status
               from c join marts.dim_participant d on d.contact_email = c.contact_email
               join linkage.int_household h on h.participant_id = d.participant_id
               join linkage.int_household_year_consent s on s.household_id = h.household_id and s.participation_year = ?)
        select (select count(*) from c), count(distinct contact_email) filter (where marketing_status = 'GRANTED_FULL') from hh""", [fy]).fetchone()
    v.update(contacts=n0(cts[0]), contacts_full=n0(cts[1]))

    # minimization (`make minimize`): evaluation.eval_minimization_tradeoff, headline matcher; V0 is the full record, V2 the data standard
    mz = {r[0]: r for r in q("select variant_id, pct_unique, sibling_or_twin_false_merges, in_standard from evaluation.eval_minimization_tradeoff where is_headline_matcher")}
    v0 = next(r for k, r in mz.items() if k.startswith("V0"))
    std = next(r for r in mz.values() if r[3])
    v.update(min_unique_v0=f"{v0[1]:.0f}", min_unique_v2=f"{std[1]:.0f}", min_sib_v0=str(v0[2]), min_sib_v2=str(std[2]))

    # deletion (`make retention-vs-deletion`): retention.mart_retention_vs_deletion, identity re-run on anonymized inputs
    dl = {r[0]: r for r in q("select metric, identity_rebuilt_change from retention.mart_retention_vs_deletion")}
    steps = [dl[f"retention_at_step_{k}"][1] for k in (1, 2, 3)]
    v.update(del_inflate=f"{100 * dl['participants'][1]:.0f}", del_retention=f"{-100 * sum(steps) / len(steps):.0f}")     # "about": the mean fall over the three steps
    return v


def render_regions(con) -> dict[str, str]:
    v = numbers(con)
    return {TABLE_TAG: TABLE.format(**v), P5_TAG: P5.format(**v)}


def apply(text: str, regions: dict[str, str]) -> str:
    for tag, body in regions.items():
        start, end = marker(tag), marker(tag, end=True)
        if start not in text or end not in text:
            raise SystemExit(f"README.md has no {start} ... {end} region")
        head, rest = text.split(start, 1)
        _, tail = rest.split(end, 1)
        text = head + start + "\n" + body + "\n" + end + tail
    return text


def current_regions(text: str) -> dict[str, str]:
    out = {}
    for tag in (TABLE_TAG, P5_TAG):
        m = re.search(re.escape(marker(tag)) + r"\n(.*?)\n" + re.escape(marker(tag, end=True)), text, re.S)
        out[tag] = m.group(1) if m else ""
    return out


def changed_numbers(old: str, new: str) -> list[str]:
    """Word-level differences between the README block and the generated block, as 'old -> new'."""
    a, b = re.findall(r"\S+", old), re.findall(r"\S+", new)
    out = []
    for op, i1, i2, j1, j2 in difflib.SequenceMatcher(None, a, b, autojunk=False).get_opcodes():
        if op != "equal":
            ctx = " ".join(a[max(0, i1 - 5):i1])
            out.append(f"...{ctx} [{' '.join(a[i1:i2])}] -> [{' '.join(b[j1:j2])}]")
    return out


def main(argv: list[str]) -> int:
    if not DB.exists():
        print("no warehouse: run `make all-phases` first", file=sys.stderr)
        return 2
    con = duckdb.connect(str(DB), read_only=True)
    try:
        regions = render_regions(con)
    finally:
        con.close()
    text = README.read_text(encoding="utf-8")
    if "--diff" in argv:
        cur = current_regions(text)
        for tag, body in regions.items():
            diffs = changed_numbers(cur[tag], body)
            print(f"{tag}: {len(diffs)} change(s)")
            for d in diffs:
                print("  ", d)
        return 0
    new = apply(text, regions)
    if "--check" in argv:
        if new != text:
            print("README.md results are out of date with the warehouse: run `make docs`", file=sys.stderr)
            return 1
        print("README results OK")
        return 0
    README.write_text(new, encoding="utf-8")
    print("wrote README.md results table and Phase 5 results")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
